{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.sru_store_sku_grain_dump AS WITH STORE_MASTER AS ( SELECT TRIM(CAST(BRANCH_CODE AS VARCHAR)) AS STORE_CODE, MAX(MARKETPLACE_MAPPED) AS STORE_NAME FROM snitch_db.maplemonk.offline_master WHERE BRANCH_CODE NOT IN ( 157,152,146,104,155,123,139,154,120,94,76,98 ) GROUP BY 1 ), STORE_COUNT AS ( SELECT COUNT(DISTINCT STORE_CODE) AS TOTAL_STORE_COUNT FROM STORE_MASTER ), META_MAP AS ( SELECT UPPER(TRIM(SKU_GROUP)) AS SKU_GROUP, MAX(NULLIF(TRIM(CATEGORY), \'\')) AS CATEGORY, MAX(NULLIF(TRIM(L1_CATEGORY), \'\')) AS L1_CATEGORY, MAX( CASE WHEN LOWER(TRIM(META1)) = \'unmapped\' THEN NULL ELSE NULLIF(TRIM(META1), \'\') END ) AS META1, MAX( CASE WHEN LOWER(TRIM(META2)) = \'unmapped\' THEN NULL ELSE NULLIF(TRIM(META2), \'\') END ) AS META2, MAX( CASE WHEN LOWER(TRIM(META3)) = \'unmapped\' THEN NULL ELSE NULLIF(TRIM(META3), \'\') END ) AS META3 FROM snitch_db.maplemonk.meta_mapping_cogs_sku WHERE SKU_GROUP IS NOT NULL GROUP BY 1 ), WH_BASE AS ( SELECT UPPER(TRIM(SKU_GROUP)) AS SKU_GROUP, SUM(COALESCE(XS_UNITS, 0)) AS XS_UNITS, SUM(COALESCE(S_UNITS, 0)) AS S_UNITS, SUM(COALESCE(M_UNITS, 0)) AS M_UNITS, SUM(COALESCE(L_UNITS, 0)) AS L_UNITS, SUM(COALESCE(XL_UNITS, 0)) AS XL_UNITS, SUM(COALESCE(XXL_UNITS, 0)) AS XXL_UNITS, SUM(COALESCE(XL3_UNITS, 0)) AS XL3_UNITS, SUM(COALESCE(XL4_UNITS, 0)) AS XL4_UNITS, SUM(COALESCE(XL5_UNITS, 0)) AS XL5_UNITS, SUM(COALESCE(XL6_UNITS, 0)) AS XL6_UNITS, SUM(COALESCE(XL7_UNITS, 0)) AS XL7_UNITS, SUM(COALESCE(XL8_UNITS, 0)) AS XL8_UNITS FROM snitch_db.maplemonk.availability_master_v2_merged WHERE SKU_GROUP IS NOT NULL GROUP BY 1 ), WH_CALC AS ( SELECT W.*, M.CATEGORY, M.L1_CATEGORY, M.META1, M.META2, M.META3, ( COALESCE(W.XS_UNITS,0) + COALESCE(W.S_UNITS,0) + COALESCE(W.M_UNITS,0) + COALESCE(W.L_UNITS,0) + COALESCE(W.XL_UNITS,0) + COALESCE(W.XXL_UNITS,0) + COALESCE(W.XL3_UNITS,0) + COALESCE(W.XL4_UNITS,0) + COALESCE(W.XL5_UNITS,0) + COALESCE(W.XL6_UNITS,0) + COALESCE(W.XL7_UNITS,0) + COALESCE(W.XL8_UNITS,0) ) AS TOTAL_WH_INV, CASE WHEN UPPER(TRIM(M.L1_CATEGORY)) = \'PLUS\' OR W.SKU_GROUP LIKE \'4MBG%\' OR W.SKU_GROUP LIKE \'4BRN%\' OR W.SKU_GROUP LIKE \'4BPL%\' OR W.SKU_GROUP LIKE \'4BTR%\' OR W.SKU_GROUP LIKE \'4BCH%\' OR W.SKU_GROUP LIKE \'4BJE%\' OR W.SKU_GROUP LIKE \'4BJK%\' OR W.SKU_GROUP LIKE \'4BSW%\' OR W.SKU_GROUP LIKE \'4BHD%\' OR W.SKU_GROUP LIKE \'4BOS%\' OR W.SKU_GROUP LIKE \'4BSHS%\' OR W.SKU_GROUP LIKE \'4BSFS%\' OR W.SKU_GROUP LIKE \'4BSH%\' OR W.SKU_GROUP LIKE \'4BBL%\' OR W.SKU_GROUP LIKE \'4BCA%\' OR W.SKU_GROUP LIKE \'4BSWT%\' OR W.SKU_GROUP LIKE \'4BCD%\' OR W.SKU_GROUP LIKE \'4BJO%\' THEN LEAST( FLOOR(COALESCE(W.XL3_UNITS,0) / 3), FLOOR(COALESCE(W.XL4_UNITS,0) / 3), FLOOR(COALESCE(W.XL5_UNITS,0) / 2), FLOOR(COALESCE(W.XL6_UNITS,0) / 2) ) ELSE LEAST( FLOOR(COALESCE(W.S_UNITS,0) / 3), FLOOR(COALESCE(W.M_UNITS,0) / 4), FLOOR(COALESCE(W.L_UNITS,0) / 4), FLOOR(COALESCE(W.XL_UNITS,0) / 3) ) END AS WAREHOUSE_LEFT_OPS FROM WH_BASE W LEFT JOIN META_MAP M ON W.SKU_GROUP = M.SKU_GROUP ), WH_FINAL AS ( SELECT *, WAREHOUSE_LEFT_OPS * CASE WHEN UPPER(TRIM(L1_CATEGORY)) = \'PLUS\' OR SKU_GROUP LIKE \'4MBG%\' OR SKU_GROUP LIKE \'4BRN%\' OR SKU_GROUP LIKE \'4BPL%\' OR SKU_GROUP LIKE \'4BTR%\' OR SKU_GROUP LIKE \'4BCH%\' OR SKU_GROUP LIKE \'4BJE%\' OR SKU_GROUP LIKE \'4BJK%\' OR SKU_GROUP LIKE \'4BSW%\' OR SKU_GROUP LIKE \'4BHD%\' OR SKU_GROUP LIKE \'4BOS%\' OR SKU_GROUP LIKE \'4BSHS%\' OR SKU_GROUP LIKE \'4BSFS%\' OR SKU_GROUP LIKE \'4BSH%\' OR SKU_GROUP LIKE \'4BBL%\' OR SKU_GROUP LIKE \'4BCA%\' OR SKU_GROUP LIKE \'4BSWT%\' OR SKU_GROUP LIKE \'4BCD%\' OR SKU_GROUP LIKE \'4BJO%\' THEN 10 ELSE 14 END AS WH_LEFT_INV_FULL, GREATEST( TOTAL_WH_INV - ( WAREHOUSE_LEFT_OPS * CASE WHEN UPPER(TRIM(L1_CATEGORY)) = \'PLUS\' OR SKU_GROUP LIKE \'4MBG%\' OR SKU_GROUP LIKE \'4BRN%\' OR SKU_GROUP LIKE \'4BPL%\' OR SKU_GROUP LIKE \'4BTR%\' OR SKU_GROUP LIKE \'4BCH%\' OR SKU_GROUP LIKE \'4BJE%\' OR SKU_GROUP LIKE \'4BJK%\' OR SKU_GROUP LIKE \'4BSW%\' OR SKU_GROUP LIKE \'4BHD%\' OR SKU_GROUP LIKE \'4BOS%\' OR SKU_GROUP LIKE \'4BSHS%\' OR SKU_GROUP LIKE \'4BSFS%\' OR SKU_GROUP LIKE \'4BSH%\' OR SKU_GROUP LIKE \'4BBL%\' OR SKU_GROUP LIKE \'4BCA%\' OR SKU_GROUP LIKE \'4BSWT%\' OR SKU_GROUP LIKE \'4BCD%\' OR SKU_GROUP LIKE \'4BJO%\' THEN 10 ELSE 14 END ), 0 ) AS WH_LEFT_INV_CUT FROM WH_CALC ), PUTAWAY_RAW AS ( SELECT UPPER( TRIM( REVERSE( SUBSTRING( REVERSE(\"Item Type skuCode\"), CHARINDEX( \'-\', REVERSE(\"Item Type skuCode\") ) + 1, LEN(\"Item Type skuCode\") ) ) ) ) AS SKU_GROUP, COALESCE( REGEXP_SUBSTR( \"Item Type skuCode\", \'[^-]+$\' ), \"Item Type skuCode\" ) AS RAW_SIZE, \"PUTAWAY_UPDATED\"::DATE AS INWARD_DATE, SUM( \"PUTAWAY_COMPLETED_QUANTITY\" ) AS QTY FROM snitch_db.maplemonk.putaway_tracking WHERE \"PUTAWAY_UPDATED\"::DATE >= \'2025-12-31\' AND LOWER(FINAL_TYPE) LIKE \'new%\' GROUP BY 1,2,3 ), PUTAWAY_MAPPED AS ( SELECT *, CASE WHEN SKU_GROUP LIKE \'SN0%\' OR SKU_GROUP LIKE \'4MSFR%\' OR SKU_GROUP LIKE \'BP%\' THEN \'NA\' WHEN SKU_GROUP LIKE \'SH0%\' THEN CASE WHEN RAW_SIZE = \'39\' THEN \'XS\' WHEN RAW_SIZE = \'40\' THEN \'S\' WHEN RAW_SIZE = \'41\' THEN \'M\' WHEN RAW_SIZE = \'42\' THEN \'L\' WHEN RAW_SIZE = \'43\' THEN \'XL\' WHEN RAW_SIZE = \'44\' THEN \'XXL\' WHEN RAW_SIZE = \'45\' THEN \'3XL\' ELSE RAW_SIZE END ELSE CASE WHEN RAW_SIZE = \'28\' THEN \'XS\' WHEN RAW_SIZE = \'30\' THEN \'S\' WHEN RAW_SIZE = \'32\' THEN \'M\' WHEN RAW_SIZE = \'34\' THEN \'L\' WHEN RAW_SIZE = \'36\' THEN \'XL\' WHEN RAW_SIZE = \'38\' THEN \'XXL\' WHEN RAW_SIZE = \'40\' THEN \'3XL\' WHEN RAW_SIZE = \'42\' THEN \'4XL\' WHEN RAW_SIZE = \'44\' THEN \'5XL\' WHEN RAW_SIZE = \'46\' THEN \'6XL\' WHEN RAW_SIZE = \'48\' THEN \'7XL\' WHEN RAW_SIZE = \'50\' THEN \'8XL\' WHEN RAW_SIZE IS NULL OR RAW_SIZE = \'\' THEN \'NA\' ELSE RAW_SIZE END END AS SIZE_MAPPED FROM PUTAWAY_RAW ), INWARD_BASE AS ( SELECT SKU_GROUP, MAX(INWARD_DATE) AS LATEST_INWARD_DATE, SUM( CASE WHEN SIZE_MAPPED = \'S\' THEN QTY ELSE 0 END ) AS S_QTY, SUM( CASE WHEN SIZE_MAPPED = \'M\' THEN QTY ELSE 0 END ) AS M_QTY, SUM( CASE WHEN SIZE_MAPPED = \'L\' THEN QTY ELSE 0 END ) AS L_QTY, SUM( CASE WHEN SIZE_MAPPED = \'XL\' THEN QTY ELSE 0 END ) AS XL_QTY, SUM( CASE WHEN SIZE_MAPPED = \'3XL\' THEN QTY ELSE 0 END ) AS XL3_QTY, SUM( CASE WHEN SIZE_MAPPED = \'4XL\' THEN QTY ELSE 0 END ) AS XL4_QTY, SUM( CASE WHEN SIZE_MAPPED = \'5XL\' THEN QTY ELSE 0 END ) AS XL5_QTY, SUM( CASE WHEN SIZE_MAPPED = \'6XL\' THEN QTY ELSE 0 END ) AS XL6_QTY FROM PUTAWAY_MAPPED GROUP BY 1 ), INWARD_FULL_SETS AS ( SELECT I.*, M.L1_CATEGORY, CASE WHEN UPPER(TRIM(M.L1_CATEGORY)) = \'PLUS\' THEN LEAST( FLOOR(COALESCE(I.XL3_QTY,0) / 3), FLOOR(COALESCE(I.XL4_QTY,0) / 3), FLOOR(COALESCE(I.XL5_QTY,0) / 2), FLOOR(COALESCE(I.XL6_QTY,0) / 2) ) ELSE LEAST( FLOOR(COALESCE(I.S_QTY,0) / 3), FLOOR(COALESCE(I.M_QTY,0) / 4), FLOOR(COALESCE(I.L_QTY,0) / 4), FLOOR(COALESCE(I.XL_QTY,0) / 3) ) END AS INWARDED_FULL_SIZE_SETS FROM INWARD_BASE I LEFT JOIN META_MAP M ON I.SKU_GROUP = M.SKU_GROUP ), INWARD_GRADE AS ( SELECT I.SKU_GROUP, COALESCE( I.INWARDED_FULL_SIZE_SETS, 0 ) AS INWARDED_FULL_SIZE_SETS, FLOOR( COALESCE( I.INWARDED_FULL_SIZE_SETS, 0 ) * 0.75 ) AS ALLOCATABLE_INWARD_OPS, CASE WHEN S.TOTAL_STORE_COUNT = 0 THEN NULL WHEN FLOOR( COALESCE( I.INWARDED_FULL_SIZE_SETS, 0 ) * 0.75 ) >= S.TOTAL_STORE_COUNT THEN \'A\' WHEN FLOOR( COALESCE( I.INWARDED_FULL_SIZE_SETS, 0 ) * 0.75 ) >= S.TOTAL_STORE_COUNT * 0.75 THEN \'B\' WHEN FLOOR( COALESCE( I.INWARDED_FULL_SIZE_SETS, 0 ) * 0.75 ) >= S.TOTAL_STORE_COUNT * 0.50 THEN \'C\' ELSE \'D\' END AS INWARD_GRADE FROM INWARD_FULL_SETS I CROSS JOIN STORE_COUNT S ), LOGIC_MRP AS ( SELECT UPPER( TRIM( CASE WHEN POSITION(\'-\' IN SKU) > 0 THEN LEFT( SKU, LENGTH(SKU) - LENGTH( REVERSE( SUBSTRING( REVERSE(SKU), 1, POSITION( \'-\', REVERSE(SKU) ) - 1 ) ) ) - 1 ) ELSE SKU END ) ) AS SKU_GROUP, MAX(MRP) AS MRP FROM snitch_db.maplemonk.logic_final_item_master GROUP BY 1 ), SALES_BASE AS ( SELECT TRIM(CAST(BRANCH_CODE AS VARCHAR)) AS STORE_CODE, UPPER(TRIM(SKU_GROUP)) AS SKU_GROUP, MAX(MRP) AS SALES_MRP, SUM( COALESCE(SUBORDER_QUANTITY,0) ) AS PERIOD_SOLD_QTY, SUM( COALESCE(SELLING_PRICE,0) ) AS REVENUE FROM SNITCH_DB.MAPLEMONK.STORE_FACT_ITEMS_OFFLINE WHERE ORDER_DATE >= \'2026-01-01\' AND ORDER_DATE NOT BETWEEN \'2026-01-01\' AND \'2026-01-31\' AND ORDER_DATE NOT BETWEEN \'2026-06-26\' AND \'2026-07-31\' AND BRANCH_CODE NOT IN ( 157,152,146,104,155,123, 139,154,120,94,76,98 ) AND DOC_PREFIX NOT IN ( \'OMS\', \'QCOM\' ) AND SKU NOT LIKE \'%CB%\' AND SKU NOT LIKE \'8909%\' AND SKU NOT LIKE \'NT0%\' AND SKU NOT LIKE \'%UNIFORM%\' AND SKU NOT LIKE \'%GIFT%\' GROUP BY 1,2 ), SALES_MRP_FALLBACK AS ( SELECT SKU_GROUP, MAX(SALES_MRP) AS SALES_MRP FROM SALES_BASE GROUP BY 1 ), LIVE_DATE_MASTER AS ( SELECT UPPER(TRIM(SKU_GROUP)) AS SKU_GROUP, MAX(FINAL_LIVE_DATE)::DATE AS LIVE_DATE FROM snitch_db.maplemonk.base_product GROUP BY 1 ), SKU_MASTER AS ( SELECT W.SKU_GROUP, COALESCE( I.INWARD_GRADE, \'D\' ) AS INWARD_GRADE, W.CATEGORY, W.L1_CATEGORY, W.META1, W.META2, W.META3, COALESCE( L.MRP, S.SALES_MRP ) AS MRP, CASE WHEN COALESCE( L.MRP, S.SALES_MRP ) IS NULL THEN \'UNKNOWN\' WHEN COALESCE( L.MRP, S.SALES_MRP ) <= 500 THEN \'0-500\' ELSE CONCAT( ( CEIL( COALESCE( L.MRP, S.SALES_MRP ) / 500.0 ) - 1 ) * 500, \'-\', CEIL( COALESCE( L.MRP, S.SALES_MRP ) / 500.0 ) * 500 ) END AS MRP_BUCKET, D.LIVE_DATE, W.WAREHOUSE_LEFT_OPS, W.WH_LEFT_INV_FULL, W.WH_LEFT_INV_CUT FROM WH_FINAL W LEFT JOIN INWARD_GRADE I ON W.SKU_GROUP = I.SKU_GROUP LEFT JOIN LOGIC_MRP L ON W.SKU_GROUP = L.SKU_GROUP LEFT JOIN SALES_MRP_FALLBACK S ON W.SKU_GROUP = S.SKU_GROUP LEFT JOIN LIVE_DATE_MASTER D ON W.SKU_GROUP = D.SKU_GROUP ), GRAIN_SALES_BASE AS ( SELECT S.STORE_CODE, SM.CATEGORY, SM.L1_CATEGORY, SM.META1, SM.META2, SM.META3, SM.MRP_BUCKET, SUM( COALESCE(S.REVENUE,0) ) AS STORE_GRAIN_REVENUE FROM SALES_BASE S INNER JOIN SKU_MASTER SM ON S.SKU_GROUP = SM.SKU_GROUP GROUP BY S.STORE_CODE, SM.CATEGORY, SM.L1_CATEGORY, SM.META1, SM.META2, SM.META3, SM.MRP_BUCKET ), GRAIN_MASTER AS ( SELECT DISTINCT CATEGORY, L1_CATEGORY, META1, META2, META3, MRP_BUCKET FROM SKU_MASTER ), STORE_GRAIN_UNIVERSE AS ( SELECT S.STORE_CODE, S.STORE_NAME, G.CATEGORY, G.L1_CATEGORY, G.META1, G.META2, G.META3, G.MRP_BUCKET FROM STORE_MASTER S CROSS JOIN GRAIN_MASTER G ), STORE_GRAIN_REVENUE AS ( SELECT U.STORE_CODE, U.STORE_NAME, U.CATEGORY, U.L1_CATEGORY, U.META1, U.META2, U.META3, U.MRP_BUCKET, COALESCE( G.STORE_GRAIN_REVENUE, 0 ) AS STORE_GRAIN_REVENUE FROM STORE_GRAIN_UNIVERSE U LEFT JOIN GRAIN_SALES_BASE G ON U.STORE_CODE = G.STORE_CODE AND EQUAL_NULL( U.CATEGORY, G.CATEGORY ) AND EQUAL_NULL( U.L1_CATEGORY, G.L1_CATEGORY ) AND EQUAL_NULL( U.META1, G.META1 ) AND EQUAL_NULL( U.META2, G.META2 ) AND EQUAL_NULL( U.META3, G.META3 ) AND EQUAL_NULL( U.MRP_BUCKET, G.MRP_BUCKET ) ), STORE_GRAIN_TOTAL AS ( SELECT *, SUM(STORE_GRAIN_REVENUE) OVER ( PARTITION BY CATEGORY, L1_CATEGORY, META1, META2, META3, MRP_BUCKET ) AS TOTAL_GRAIN_REVENUE FROM STORE_GRAIN_REVENUE ), STORE_GRAIN_PARETO AS ( SELECT *, SUM(STORE_GRAIN_REVENUE) OVER ( PARTITION BY CATEGORY, L1_CATEGORY, META1, META2, META3, MRP_BUCKET ORDER BY STORE_GRAIN_REVENUE DESC, STORE_CODE ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS CUMULATIVE_REVENUE, SUM(STORE_GRAIN_REVENUE) OVER ( PARTITION BY CATEGORY, L1_CATEGORY, META1, META2, META3, MRP_BUCKET ORDER BY STORE_GRAIN_REVENUE DESC, STORE_CODE ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) - STORE_GRAIN_REVENUE AS PREVIOUS_CUMULATIVE_REVENUE FROM STORE_GRAIN_TOTAL ), STORE_GRAIN_GRADE AS ( SELECT STORE_CODE, STORE_NAME, CATEGORY, L1_CATEGORY, META1, META2, META3, MRP_BUCKET, STORE_GRAIN_REVENUE, CASE WHEN TOTAL_GRAIN_REVENUE <= 0 THEN \'D\' WHEN PREVIOUS_CUMULATIVE_REVENUE / NULLIF( TOTAL_GRAIN_REVENUE, 0 ) < 0.25 THEN \'A\' WHEN PREVIOUS_CUMULATIVE_REVENUE / NULLIF( TOTAL_GRAIN_REVENUE, 0 ) < 0.50 THEN \'B\' WHEN PREVIOUS_CUMULATIVE_REVENUE / NULLIF( TOTAL_GRAIN_REVENUE, 0 ) < 0.75 THEN \'C\' ELSE \'D\' END AS GRAIN_GRADE FROM STORE_GRAIN_PARETO ), STORE_SKU_ACTUAL AS ( SELECT TRIM( CAST( BRANCH_CODE AS VARCHAR ) ) AS STORE_CODE, UPPER( TRIM(SKU_GROUP) ) AS SKU_GROUP, SUM( COALESCE(TOTAL_SALES,0) ) AS SOLD_QTY, SUM( COALESCE(INVENTORY,0) + COALESCE(JIT_QTY,0) ) AS CURRENT_STORE_INV, SUM( COALESCE(TOTAL_SALES,0) + COALESCE(INVENTORY,0) + COALESCE(JIT_QTY,0) ) AS ALLOCATED_QTY FROM snitch_db.maplemonk.offline_master WHERE BRANCH_CODE NOT IN ( 157,152,146,104,155,123, 139,154,120,94,76,98 ) GROUP BY 1,2 ), STORE_SKU_UNIVERSE AS ( SELECT S.STORE_CODE, S.STORE_NAME, K.SKU_GROUP, K.INWARD_GRADE, K.CATEGORY, K.L1_CATEGORY, K.META1, K.META2, K.META3, K.MRP_BUCKET, K.LIVE_DATE, K.WAREHOUSE_LEFT_OPS, K.WH_LEFT_INV_FULL, K.WH_LEFT_INV_CUT FROM STORE_MASTER S CROSS JOIN SKU_MASTER K ), FINAL_MASTER AS ( SELECT U.STORE_CODE, U.STORE_NAME, U.SKU_GROUP, U.INWARD_GRADE, U.CATEGORY, U.L1_CATEGORY, U.META1, U.META2, U.META3, U.MRP_BUCKET, U.LIVE_DATE, CASE WHEN COALESCE( A.ALLOCATED_QTY, 0 ) > 0 THEN 1 ELSE 0 END AS ALLOCATED_OPS, COALESCE( A.ALLOCATED_QTY, 0 ) AS ALLOCATED_QTY, COALESCE( A.SOLD_QTY, 0 ) AS SOLD_QTY, COALESCE( G.GRAIN_GRADE, \'D\' ) AS GRAIN_GRADE, U.WAREHOUSE_LEFT_OPS AS WH_LEFT_OPS, U.WH_LEFT_INV_FULL, U.WH_LEFT_INV_CUT FROM STORE_SKU_UNIVERSE U LEFT JOIN STORE_SKU_ACTUAL A ON U.STORE_CODE = A.STORE_CODE AND U.SKU_GROUP = A.SKU_GROUP LEFT JOIN STORE_GRAIN_GRADE G ON U.STORE_CODE = G.STORE_CODE AND EQUAL_NULL( U.CATEGORY, G.CATEGORY ) AND EQUAL_NULL( U.L1_CATEGORY, G.L1_CATEGORY ) AND EQUAL_NULL( U.META1, G.META1 ) AND EQUAL_NULL( U.META2, G.META2 ) AND EQUAL_NULL( U.META3, G.META3 ) AND EQUAL_NULL( U.MRP_BUCKET, G.MRP_BUCKET ) ) SELECT STORE_CODE, STORE_NAME, SKU_GROUP, INWARD_GRADE, CATEGORY, L1_CATEGORY AS L1, META1, META2, META3, MRP_BUCKET, LIVE_DATE, ALLOCATED_OPS, ALLOCATED_QTY, SOLD_QTY, GRAIN_GRADE, WH_LEFT_OPS, WH_LEFT_INV_FULL, WH_LEFT_INV_CUT FROM FINAL_MASTER WHERE LIVE_DATE > \'2026-07-01\' AND WH_LEFT_OPS > 5 ORDER BY STORE_CODE, GRAIN_GRADE, SKU_GROUP ; CREATE OR REPLACE TABLE snitch_db.maplemonk.sru_store_sku_grain_summary AS SELECT INWARD_GRADE, L1, CATEGORY, meta1, meta2, meta3, COUNT(DISTINCT CASE WHEN GRAIN_GRADE = \'A\' THEN STORE_CODE END) AS A_STORE_OPS, SUM(CASE WHEN GRAIN_GRADE = \'A\' THEN ALLOCATED_QTY ELSE 0 END) AS A_STORE_QTY, ROUND( SUM(CASE WHEN GRAIN_GRADE = \'A\' THEN ALLOCATED_QTY ELSE 0 END) / NULLIF( COUNT(DISTINCT CASE WHEN GRAIN_GRADE = \'A\' THEN STORE_CODE END), 0 ), 2 ) AS A_AVG_QTY_PER_OPT, COUNT(DISTINCT CASE WHEN GRAIN_GRADE = \'B\' THEN STORE_CODE END) AS B_STORE_OPS, SUM(CASE WHEN GRAIN_GRADE = \'B\' THEN ALLOCATED_QTY ELSE 0 END) AS B_STORE_QTY, ROUND( SUM(CASE WHEN GRAIN_GRADE = \'B\' THEN ALLOCATED_QTY ELSE 0 END) / NULLIF( COUNT(DISTINCT CASE WHEN GRAIN_GRADE = \'B\' THEN STORE_CODE END), 0 ), 2 ) AS B_AVG_QTY_PER_OPT, COUNT(DISTINCT CASE WHEN GRAIN_GRADE = \'C\' THEN STORE_CODE END) AS C_STORE_OPS, SUM(CASE WHEN GRAIN_GRADE = \'C\' THEN ALLOCATED_QTY ELSE 0 END) AS C_STORE_QTY, ROUND( SUM(CASE WHEN GRAIN_GRADE = \'C\' THEN ALLOCATED_QTY ELSE 0 END) / NULLIF( COUNT(DISTINCT CASE WHEN GRAIN_GRADE = \'C\' THEN STORE_CODE END), 0 ), 2 ) AS C_AVG_QTY_PER_OPT, COUNT(DISTINCT CASE WHEN GRAIN_GRADE = \'D\' THEN STORE_CODE END) AS D_STORE_OPS, SUM(CASE WHEN GRAIN_GRADE = \'D\' THEN ALLOCATED_QTY ELSE 0 END) AS D_STORE_QTY, ROUND( SUM(CASE WHEN GRAIN_GRADE = \'D\' THEN ALLOCATED_QTY ELSE 0 END) / NULLIF( COUNT(DISTINCT CASE WHEN GRAIN_GRADE = \'D\' THEN STORE_CODE END), 0 ), 2 ) AS D_AVG_QTY_PER_OPT FROM snitch_db.maplemonk.sru_store_sku_grain_dump GROUP BY 1,2,3,4,5,6 ORDER BY L1, CASE INWARD_GRADE WHEN \'A\' THEN 1 WHEN \'B\' THEN 2 WHEN \'C\' THEN 3 WHEN \'D\' THEN 4 ELSE 5 END, CATEGORY;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            